Tool response:
Tool: get_options_chain
Description: Fetch options chain data for a specified symbol, filtered by expiration date, option type, strike price range, and minimum open interest.
Returns call options with strike prices between $180 and $200 and open interest above 5,000 for the next monthly expiration date.
Parameters:
    {
      "type": "object",
      "properties": {
        "symbol": {
          "type": "string",
          "description": "Stock ticker symbol (e.g., AAPL)",
          "title": "Symbol"
        },
        "expiration_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Specific expiration date (YYYY-MM-DD). If omitted, uses next monthly expiration.",
          "title": "Expiration Date"
        },
        "option_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Option type (call or put). Defaults to 'call'.",
          "default": "call",
          "title": "Option Type"
        },
        "min_strike": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum strike price filter. Defaults to 180.",
          "default": 180.0,
          "title": "Min Strike"
        },
        "max_strike": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "description": "Maximum strike price filter. Defaults to 200.",
          "default": 200.0,
          "title": "Max Strike"
        },
        "min_open_interest": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "description": "Minimum open interest filter. Defaults to 5000.",
          "default": 5000,
          "title": "Min Open Interest"
        }
      },
      "required": [
        "symbol"
      ]
    }
